R1 = ['Түр зогсож асуулт асуух хуудаснуудыг тэмдэглэн асуултыг бичих',
      'Уншиж байхдаа танилцуулах үгсийг хуудасны дугаарын хамт тэмдэглэх',
      'Уншиж дуусаад асуух асуулт, ярилцах зүйлс, хийх бүтээл']
R2 = ['Номын тухай эргэн санах: Эхлэл, өрнөл, төгсгөл хэсгүүдтэй холбоотой энгийн асуултууд асуух'] + R1
R3 = ['Уншихын өмнө', 'Уншиж байхдаа', 'Уншиж дуусаад']

R3_BEFORE = ('Энэ номыг бид хамтдаа 2 удаа уншчихсан учраас номын нэрийг та нар мэдэж байгаа шүү дээ. '
             'Энэ номын нэр юу билээ? гэх зэргээр хүүхдийг эхнээс нь татан оролцуулна.\n')


def book(days, title, author, goals, summary, words, r1, r2, r3, text):
    return {
        'days': days, 'book': title, 'author': author, 'goals': '\n'.join(goals), 'summary': summary,
        'words': words,
        'r1': dict(zip(R1, ['\n'.join(x) for x in r1])),
        'r2': dict(zip(R2, ['\n'.join(x) for x in r2])),
        'r3': dict(zip(R3, [R3_BEFORE + '\n'.join(r3[0]), '\n'.join(r3[1]), '\n'.join(r3[2])])),
        'text': '\n'.join(f'Хэсэг {i}. {t}' for i, t in enumerate(text, 1)),
    }


